INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(126148, 'ruRU', '', 'Благодарю тебя, малыш.', 24330),
(126149, 'ruRU', '', 'Эй! Помоги мне снять эти кандалы!', 24330),
(126151, 'ruRU', '', 'Я видел, что творит твой так называемый "дар", демон. Я никогда не присоединюсь к вашему роду!', 24330),
(126155, 'ruRU', '', 'Угомонись, шут. Тут на кону нечто большее, чем твой жалкий вождь!', 24330),
(126164, 'ruRU', '', 'Ах, Убийцса $n. Пока ты здесь, можешь и помочь.', 24330),
(126165, 'ruRU', '', 'Я могла бы справиться с ним... со временем. Мои благодарноссти.', 24330),
(126178, 'ruRU', '', 'Я рада, что ты сдержал наш договор, Убийцса $n. Пожалуй, я ошиблась на твой счёт.', 24330),
(126182, 'ruRU', '', 'Я чуть не сошла с ума после стольких месяцев на этом вонючссем корабле. К тому же, ситуация требовала кого-то с моими навыками...\n\nПожалуй, мне стоило сначала клонировать себя.', 24330),
(126183, 'ruRU', '', 'Увидимсся там.', 24330),
(126184, 'ruRU', '', 'Ты позор, Лексера! Ты поклялась защищать наш город.', 24330),
(126185, 'ruRU', '', 'Ты заплатишь жизнью за своё предательство!', 24330),
(126186, 'ruRU', '', 'Тебя послала Сиренна? Неужели она действительно встала на сторону чужака против своего народа?', 24330),
(126188, 'ruRU', '', 'Она поймёт, что сделала неверный выбор. Наш истинный союзник - Пылающий Легион!', 24330),
(126196, 'ruRU', '', 'Твоя настойчивость раздражает! Мои любимые бесы, защитите меня!', 24330),
(126197, 'ruRU', '', 'Ты гонишься за мной слишком далеко, $n. Мои драгоценные бесы заставят тебя страдать больше, чем ты можешь представить.', 24330),
(126198, 'ruRU', '', 'Почему это обязательно должны быть демонысс?', 24330),
(126199, 'ruRU', '', 'Ну конечно, это меня послалисс сюда.', 24330),
(126200, 'ruRU', '', 'Серые камнисс и зелёный огонь. Снова.', 24330),
(126201, 'ruRU', '', 'Что ж, да, у меня действительно нет короны. Благодарю, что заметил.\n\n<Посланник весело улыбается тебе.>', 24330),
(126203, 'ruRU', '', 'Ах, ты же знаешь...\n\nОни где-то здесь.\n\nИди уже!', 24330),
(126209, 'ruRU', '', 'Похоже, прислужники Круула были здесь совсем недавно.', 24330),
(126217, 'ruRU', '', 'Я так, так устал. И всё же я не могу отдохнуть, пока не буду уверен, что наш орден выживет.', 24330),
(126222, 'ruRU', '', 'Верховный жрец! У меня важные вести для тебя, да.', 24330),
(126224, 'ruRU', '', 'Море пока спокойно, даже так близко к Мальстрёму.', 24330),
(126227, 'ruRU', '', 'И что это вообще значит?', 24330),
(126231, 'ruRU', '', 'Мы подходим к тому, что похоже на вход в хранилище.', 24330),
(126235, 'ruRU', '', 'Ну, похоже, тебе больше не придётся искать рычаги да переключатели, Бранн!', 24330),
(126245, 'ruRU', '', 'Эй, мистер Хранитель, да во имя Кузни, что такое Искатель?', 24330),
(126250, 'ruRU', '', 'Значит, здесь только трое?', 24330),
(126261, 'ruRU', '', 'Исчадия Света, едва принадлежащие этому миру. Хорошее развеивание должно их рассеять.', 24330),
(126265, 'ruRU', '', 'Хм, хранитель отключается. Должно быть, эта камера истратила всю свою энергию.', 24330),
(126266, 'ruRU', '', 'Больше никого не осталось, чтобы заботиться об этих бедных созданиях!', 24330),
(126270, 'ruRU', '', 'Согласен. Верховный жрец, дай нам время, чтобы вписать их в летописи Света. Встретимся в Храме Пустосвета.', 24330),
(126276, 'ruRU', '', 'Скверные Тотемы захватывают моих людей, стремясь вербовать их в свои ряды. Это зло нужно остановить!', 24330),
(126293, 'ruRU', '', 'Затерянное титанское хранилище... в безупречном состоянии? Это точно войдёт в книгу рекордов! Что, по-твоему, в этих пузырях, а?', 24330),
(126299, 'ruRU', '', 'Я бы присоединился к тебе, но эта пещера рассчитана на плотяных. Направь мою силу через свой Камень Рока и сокруши наших врагов!', 24330),
(126300, 'ruRU', '', 'Последняя просьба о помощи, плотяной. Тандераану нужна твоя помощь.', 24330),
(126302, 'ruRU', '', 'Возможно, это можно устроить. Великий мастер $n, ты не очень хорошо выглядишь. Тебе стоит вернуться на Вершину Безмятежности!', 24330),
(126307, 'ruRU', '', 'Галиус, дорогой, эти незваные гости прерывают наше время вдвоём! РАЗБЕРИСЬ С НИМИ!', 24330),
(126311, 'ruRU', '', 'Хорошую помощь так трудно найти. Видимо, придётся разобраться... самой.', 24330);
